// Converte a resposta do Firestore em itens simples e escolhe QUEM capturar.
//
// ATENÇÃO — DUPLICAÇÃO CONSCIENTE: esta lista precisa bater com as lojas que
// têm busca="capturada" em coletor/lojas.py. É o único lugar do workflow que
// repete conhecimento do repositório. Mudou lá, muda aqui.
//
// PRECISA SER O DOMÍNIO COMPLETO. A comparação é por sufixo de rótulo
// (host === d || host.endsWith('.' + d)), então 'pichau' NÃO casa com
// 'www.pichau.com.br' — casa zero, em silêncio, e o workflow "roda com sucesso"
// sem capturar nada.
//
// A KaBuM fica de fora de propósito: ela responde direto do runner, e depender
// do n8n para ela seria trocar o que funciona pelo que talvez funcione.
// As outras três tomam 403 do datacenter — medido em 2026-08-13, com as MESMAS
// URLs respondendo 200 de rede residencial.
const DOMINIOS_PARA_CAPTURAR = [
  'pichau.com.br',
  'terabyteshop.com.br',
  'amazon.com.br',
];

// Host completo, sem depender do global `URL` (o editor do Code node não o
// reconhece e sublinha em vermelho). Mesma normalização de `_host()` em
// coletor/lojas.py: fora userinfo, fora porta, fora 'www.'.
//
// NÃO troque por url.split('.')[1]. Isso devolve só o segundo rótulo e tem dois
// furos medidos em 2026-08-13:
//   'https://pichau.com.br/x'        -> 'com'    (sem www, a fonte some calada)
//   'https://www.pichau.evil.com/x'  -> 'pichau' (domínio impostor PASSA)
function hostDaUrl(url) {
  const achado = /^https?:\/\/([^/?#]+)/i.exec(url || '');
  if (!achado) return '';
  return achado[1].toLowerCase().split('@').pop().split(':')[0].replace(/^www\./, '');
}

const saida = [];

for (const item of $input.all()) {
  const doc = item.json.document;

  // A resposta traz entradas de readTime sem documento; ignore.
  if (!doc || !doc.name) continue;

  const campos = doc.fields || {};
  const url = campos.url?.stringValue;

  if (!url) continue;

  // .../fontes/{fonteId} -> o id é o último segmento do path
  const fonteId = doc.name.split('/').pop();
  const loja = campos.loja?.stringValue || '';

  const host = hostDaUrl(url);
  if (!host) continue;   // URL malformada: nada a buscar

  const capturar = DOMINIOS_PARA_CAPTURAR.some(
    (d) => host === d || host.endsWith('.' + d),
  );
  if (!capturar) continue;

  saida.push({ json: { fonteId, url, loja, host } });
}

if (saida.length === 0) {
  // Sem isto o workflow "tem sucesso" sem fazer nada, e você descobre semanas
  // depois que a lista estava vazia.
  console.warn(
    'Nenhuma fonte para capturar. DOMINIOS_PARA_CAPTURAR está vazia? ' +
    'Ela precisa bater com as lojas busca="capturada" em coletor/lojas.py.',
  );
}

return saida;

// Enxuga o HTML e monta o documento no formato do Firestore REST.
//
// SEM require() e SEM CompressionStream: o sandbox deste n8n recusa os dois
// ("Module 'zlib' is disallowed", e CompressionStream indisponível). Sobra
// enxugar o HTML até caber no teto de 1 MiB por documento do Firestore.
//
// MEDIDO em 2026-08-13, com o preço conferido em cada variante:
//
//   Amazon    1.209 KB -> 940 KB (só style/comentários) -> 655 KB (sem scripts)
//   Pichau      402 KB -> 178 KB                        -> 64 KB, PERDE O PREÇO
//   Terabyte    196 KB -> 158 KB                        -> 143 KB
//
// O corte de <script> é o que dá folga de verdade, mas quebra a Pichau: o preço
// à vista dela vive num <script> comum, não no ld+json. Daí a exceção abaixo.

const TETO_FIRESTORE = 1048576;   // 1 MiB por documento

// Domínios cujo preço mora num <script> COMUM. Para todos os outros, só o
// ld+json é preservado — que é onde KaBuM, Terabyte e Pichau publicam o Product,
// e a Amazon nem usa (o preço dela está no DOM).
const PRECISA_DOS_SCRIPTS = ['pichau.com.br'];

const html = $json.data ?? '';
const { fonteId, url, loja, host } = $('Escolher o que capturar1').item.json;

if (typeof html !== 'string' || html.length < 500) {
  throw new Error(
    `${loja}: resposta vazia ou curta demais (${html.length} chars) para ${url}. ` +
    'A loja bloqueou, ou responseFormat não é text.',
  );
}

// Rede de segurança contra o erro nº 1 da integração: HTML que passou por JSON
// chega com as aspas escapadas, nada casa, e o coletor reporta `sem_jsonld`
// apontando para a loja em vez de para o transporte.
const amostra = html.slice(0, 100000);
const aspas = (amostra.match(/"/g) || []).length;
const escapadas = (amostra.match(/\\"/g) || []).length;
if (aspas > 0 && escapadas / aspas >= 0.5) {
  throw new Error(
    `${loja}: HTML com aspas ESCAPADAS (${escapadas}/${aspas}). ` +
    'Passou por JSON.stringify. Confira responseFormat=text no nó de busca.',
  );
}

const manterScripts = PRECISA_DOS_SCRIPTS.some(
  (d) => host === d || host.endsWith('.' + d),
);

let enxuto = html
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, '')
  .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, '');

if (!manterScripts) {
  // ld+json sempre fica: é onde três das quatro lojas publicam o preço.
  enxuto = enxuto.replace(
    /<script\b[^>]*>[\s\S]*?<\/script>/gi,
    (bloco) => (/ld\+json/i.test(bloco.slice(0, 120)) ? bloco : ''),
  );
}

enxuto = enxuto.replace(/[ \t]{2,}/g, ' ').replace(/\n{2,}/g, '\n');

// Bytes UTF-8 sem Buffer nem TextEncoder: encodeURIComponent vira cada byte
// não-ASCII em %XX, e trocar cada %XX por um caractere iguala comprimento a
// contagem de bytes.
const bytes = (s) => encodeURIComponent(s).replace(/%[0-9A-F]{2}/gi, 'x').length;
const bytesEnxuto = bytes(enxuto);

if (bytesEnxuto > TETO_FIRESTORE) {
  throw new Error(
    `${loja}: ${Math.round(bytesEnxuto / 1024)} KB depois de enxugar, ainda acima ` +
    `do teto de 1 MiB. Página cresceu; considere cortar mais ou usar Cloud Storage.`,
  );
}

return [{
  json: {
    fonteId,
    loja,
    kbOriginal: Math.round(bytes(html) / 1024),
    kbNoDocumento: Math.round(bytesEnxuto / 1024),
    manterScripts,
    corpo: {
      fields: {
        url: { stringValue: url },
        html: { stringValue: enxuto },
        codificacao: { stringValue: 'texto' },
        bytes: { integerValue: String(bytesEnxuto) },
        capturadoEm: { timestampValue: new Date().toISOString() },
      },
    },
  },
}];
